from pathlib import Path
import re
text = Path('/app/train_decoder_full_out.txt').read_text()
train = {}
val = {}
section = None
for line in text.splitlines():
    if line.startswith('Training Balanced Accuracy Scores'):
        section = 'train'
        continue
    if line.startswith('Validation Balanced Accuracy Scores'):
        section = 'val'
        continue
    m = re.match(r'\s*(\d+) \(([^)]+)\): ([0-9.]+)\s+\(chance: ([0-9.]+)\)', line)
    if m:
        idx, name, score, chance = m.groups()
        rec = (name, float(score), float(chance), float(score)/float(chance))
        if section == 'train':
            train[name] = rec
        elif section == 'val':
            val[name] = rec
for name in val:
    t = train[name]
    v = val[name]
    print(name, 'train', t[1], 'val', v[1], 'chance', v[2], 'val_over_chance', round(v[3], 3), 'train_over_val', round(t[1]/v[1], 3))
